/bin/bash -lc "cat > /workspace/signature_score.py <<'PY'
import sys, math

markers = [
    'S100A8','S100A9','S100A7','S100A12','SERPINB4','SERPINB3','DEFB4A',
    'IL36G','SPRR2A','LCE3A','LCE3E','PI3','KYNU','OASL','STAT1','TCN1',
    'GJB2','GJB6','S100A7A','SPRR2B','SPRR2F','IL20','IL36A','HERC6','PARP9'
]

def main():
    inp, outp = sys.argv[1], sys.argv[2]
    samples = []
    with open(inp, 'r', encoding='utf-8') as f:
        header = f.readline().rstrip('\\n').split('\\t')
        sample_names = header[1:10]
        sample_vals = [[] for _ in sample_names]
        gene_idx = {}
        for line in f:
            if not line.strip():
                continue
            parts = line.rstrip('\\n').split('\\t')
            if len(parts) < 10:
                continue
            gene = parts[0]
            if gene not in markers:
                continue
            try:
                vals = [float(parts[i]) for i in range(1,10)]
            except ValueError:
                continue
            for i, v in enumerate(vals):
                sample_vals[i].append(math.log2(v + 1.0))
    scores = []
    for name, lvals in zip(sample_names, sample_vals):
        if not lvals:
            score = 0.0
        else:
            score = sum(lvals) / len(lvals)
        scores.append((name, score, len(lvals)))
    # sort descending by score
    scores.sort(key=lambda r: r[1], reverse=True)
    with open(outp, 'w', encoding='utf-8') as f:
        f.write('sample\\tscore\\tn_markers\\n')
        for name, score, n in scores:
            f.write(f'{name}\\t{score:.6f}\\t{n}\\n')

if __name__ == '__main__':
    main()
PY
python3 -m py_compile /workspace/signature_score.py && echo compiled"
